const BASTAR_INFO={id:"bastar-iron-craft",title:"Bastar Iron Craft (Loha Shilp)",originRegion:"Bastar & Kondagaon, Chhattisgarh",community:"Lohar Tribal Artisan Guilds",giTagStatus:"Geographical Indication (GI) Certified",material:"Wrought Iron & Recycled Scrap Iron",toolsUsed:"Charcoal Furnace, Anvil, Tongs, Chisels, Heavy Hammers",quickStats:[{label:"GI Tag Certified",value:"Chhattisgarh",icon:"🏷️"},{label:"Technique",value:"Hand Forging",icon:"🔨"},{label:"Artisan Hub",value:"Kondagaon",icon:"📍"},{label:"Raw Material",value:"Recycled Iron",icon:"⚒️"},{label:"Welding",value:"Zero Welding",icon:"⚙️"},{label:"Motifs",value:"Tribal Deities & Flora",icon:"🦌"}]},PROCESS_STEPS=[{step:1,title:"Iron Sourcing & Scrap Heating",description:"Artisans source scrap iron bars and heat them in traditional charcoal furnaces (bhatti) until malleable."},{step:2,title:"Manual Hammering & Beating",description:"Master blacksmiths manually beat red-hot iron on heavy anvils to flatten, draw out, and shape individual components."},{step:3,title:"Intricate Bending & Joinery",description:"Components are intricately twisted and joined using rivets, bends, and interlocking joints without modern welding."},{step:4,title:"Detail Chisel Carving",description:"Fine surface textures, eyes, clothing folds, and traditional tribal markings are carved into warm iron using hand chisels."},{step:5,title:"Cooling & Natural Black Finish",description:"Completed items are coated with protective oil or beeswax and cooled to develop a rich rust-resistant matte black patina."}],TRADITIONAL_DESIGNS=[{name:"Tribal Musicians & Dancers",description:"Slender human figurines holding traditional drums (mandar), flutes, and cymbals in ceremonial dance poses."},{name:"Forest Animals (Deer & Elephant)",description:"Elongated deer, peacocks, and elephants symbolizing the deep spiritual connection between Bastar tribes and nature."},{name:"Diyas & Tree Lamps (Dipa Stambha)",description:"Branching iron oil lamps featuring perching birds and multiple flame trays used in village shrines."},{name:"Tribal Deities (Budha Deo & Danteshwari)",description:"Reverent representations of tribal guardian deities protecting villages and agricultural harvests."}],ARTISAN_SPOTLIGHT={title:"Kondagaon Craft Guilds",description:"Kondagaon in Bastar district is known as the 'Craft Village' of Chhattisgarh, home to generations of Lohar master craftsmen who preserve ancestral iron forging secrets passed down orally across centuries."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Bastar_iron_craft.jpg/800px-Bastar_iron_craft.jpg",caption:"Traditional Bastar Iron Craft figurine depicting a tribal musician",category:"Artifact"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Bastar_tribal_metal_art.jpg/800px-Bastar_tribal_metal_art.jpg",caption:"Hand-forged iron oil lamp (Dipa Stambha) with bird motifs",category:"Traditional Design"}],REFERENCES=[{text:"Handicrafts Development Corporation of Chhattisgarh — Bastar Loha Shilp GI Documentation.",link:"#"},{text:"Development Commissioner (Handicrafts), Ministry of Textiles, Government of India.",link:"https://handicrafts.nic.in"},{text:"Bastar Tribal Art & Culture Research Centre, Jagdalpur.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={BASTAR_INFO:BASTAR_INFO,PROCESS_STEPS:PROCESS_STEPS,TRADITIONAL_DESIGNS:TRADITIONAL_DESIGNS,ARTISAN_SPOTLIGHT:ARTISAN_SPOTLIGHT,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});